from collections import defaultdict

class Solution:
    def smallestStringWithSwaps(self, s: str, pairs: list[list[int]]) -> str:
        parent = list(range(len(s)))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i, root_j = find(i), find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        for u, v in pairs:
            union(u, v)

        groups = defaultdict(list)
        for i in range(len(s)):
            groups[find(i)].append(i)

        res = list(s)
        for idxs in groups.values():
            chars = sorted(res[i] for i in idxs)
            idxs.sort()
            for i, c in zip(idxs, chars):
                res[i] = c

        return ''.join(res)

class Solution {
    std::vector<int> parent;
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    void unite(int i, int j) {
        int rootI = find(i), rootJ = find(j);
        if (rootI != rootJ) parent[rootI] = rootJ;
    }
public:
    std::string smallestStringWithSwaps(std::string s, std::vector<std::vector<int>>& pairs) {
        int n = s.size();
        parent.resize(n);
        std::iota(parent.begin(), parent.end(), 0);

        for (const auto& p : pairs) unite(p[0], p[1]);

        std::unordered_map<int, std::vector<int>> groups;
        for (int i = 0; i < n; ++i) groups[find(i)].push_back(i);

        for (auto& [root, idxs] : groups) {
            std::string chars = "";
            for (int i : idxs) chars += s[i];
            std::sort(chars.begin(), chars.end());
            std::sort(idxs.begin(), idxs.end());
            for (int k = 0; k < idxs.size(); ++k) s[idxs[k]] = chars[k];
        }
        return s;
    }
};

class Solution {
    int[] parent;
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    void union(int i, int j) {
        int rootI = find(i), rootJ = find(j);
        if (rootI != rootJ) parent[rootI] = rootJ;
    }

    public String smallestStringWithSwaps(String s, java.util.List<java.util.List<Integer>> pairs) {
        int n = s.length();
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        for (java.util.List<Integer> p : pairs) union(p.get(0), p.get(1));

        java.util.Map<Integer, java.util.List<Integer>> groups = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            groups.computeIfAbsent(find(i), k -> new java.util.ArrayList<>()).add(i);
        }

        char[] res = s.toCharArray();
        for (java.util.List<Integer> idxs : groups.values()) {
            java.util.List<Character> chars = new java.util.ArrayList<>();
            for (int i : idxs) chars.add(res[i]);
            java.util.Collections.sort(chars);
            java.util.Collections.sort(idxs);
            for (int k = 0; k < idxs.size(); k++) {
                res[idxs.get(k)] = chars.get(k);
            }
        }
        return new String(res);
    }
}

var smallestStringWithSwaps = function(s, pairs) {
    const n = s.length;
    const parent = Array.from({ length: n }, (_, i) => i);
    const find = (i) => {
        if (parent[i] !== i) parent[i] = find(parent[i]);
        return parent[i];
    };
    const union = (i, j) => {
        const rootI = find(i), rootJ = find(j);
        if (rootI !== rootJ) parent[rootI] = rootJ;
    };

    for (const [u, v] of pairs) union(u, v);

    const groups = new Map();
    for (let i = 0; i < n; i++) {
        const root = find(i);
        if (!groups.has(root)) groups.set(root, []);
        groups.get(root).push(i);
    }

    const res = s.split('');
    for (const idxs of groups.values()) {
        const chars = idxs.map(i => res[i]).sort();
        idxs.sort((a, b) => a - b);
        for (let k = 0; k < idxs.length; k++) {
            res[idxs[k]] = chars[k];
        }
    }
    return res.join('');
};
